-- Durable cache for examiner prompt audio generated by the pinned Speaches TTS model and voice.

create table public.speaking_examiner_tts_assets (
  cache_key text primary key,
  model text not null,
  voice text not null,
  prompt_hash text not null,
  storage_key text not null unique,
  mime_type text not null check (mime_type = 'audio/wav'),
  size_bytes bigint not null check (size_bytes > 0),
  created_at timestamptz not null default now(),
  constraint speaking_examiner_tts_cache_key_check check (cache_key ~ '^[0-9a-f]{64}$'),
  constraint speaking_examiner_tts_prompt_hash_check check (prompt_hash ~ '^[0-9a-f]{64}$')
);

alter table public.speaking_exam_turns
  add column prompt_audio_cache_key text
  references public.speaking_examiner_tts_assets(cache_key) on delete restrict;

create index idx_speaking_exam_turns_prompt_audio
  on public.speaking_exam_turns(prompt_audio_cache_key)
  where prompt_audio_cache_key is not null;

alter table public.speaking_examiner_tts_assets enable row level security;

comment on table public.speaking_examiner_tts_assets is
  'Private object-storage references for deduplicated Speaches-generated examiner prompt audio.';
